/* ===== 👑 TRANG BỊ HOÀNG KIM (ui/101-trang-bi-hoang-kim.js) — Fix313 — nạp SAU ui/100-o-hoang-kim.js và world/102-lang-tan-thu-3.js =====
 * 4 món: 0 Mão (Long Quan) · 1 Kiếm · 2 Nhẫn · 3 Dây chuyền. Icon cắt từ ảnh người dùng gửi (base64 WebP trong ICON).
 * CHẾ TẠO: 🏠 Nhà Trang Sức Hoàng Kim (Làng Tân Thủ 2) → chạm nhà → chọn món → chọn 10 trang bị Thiên Thần (r=5, tuỳ ý, không phải đồ khoá c, không phải đồ thú nuôi)
 *   + 1.000 💎 Linh Thạch (LT.spend: trừ khoá của nhân vật trước, hết mới trừ không khoá; cần đăng nhập ☁). Tỉ lệ thành công 50%.
 *   THẤT BẠI: mất cả 10 trang bị lẫn Linh Thạch. Mỗi ô chỉ chế 1 món (hiện chỉ cấp 1; nâng cấp 2→10 cập nhật sau: CF.maxMake).
 * MẶC: món chế xong tự nằm vào ô Hoàng Kim tương ứng (tab 🎒 Túi, ui/100). Dùng được khi nhân vật Lv60+ (CF.useLv).
 * CHỈ SỐ mỗi món cấp 1: +2% Công · +2% Thủ · +2% Máu · +1000 Năng lượng (MP cộng phẳng) — bảng CF.stat[cấp].
 * BỘ (đếm số món CÙNG CẤP): 2 món: +20% sát thương kỹ năng (+5%/cấp) · 3 món: khi tung thần thông có 1% (+1%/cấp) gây ×3 sát thương ·
 *   4 món: kỹ năng "Địa Tiên" tự tung mỗi CF.dtCd giây khi có địch: gây 100% Công (+30%/cấp) lên số địch = cấp (tối đa 10), bỏ qua 30% giáp.
 * Lưu: PS[cur].hkg = {s:[null|{l:cấp,t:thời gian}×4]} (theo từng nhân vật). Móc (không sửa core): ZC.pa/pd/ph/pm · dm() (SKF=1 = đòn kỹ năng) · ZC.tick · HK (ui/100) · TT2.houses[1].open.
 * Gỡ = xoá thẻ script trong index.html. API: HKG.openCraft() · HKG.give(slot,cấp) (thử nghiệm) · HKG.cfg */
(function(){
'use strict';
if(window.HKG||typeof ui!=='function'||typeof ZC==='undefined'||typeof dm!=='function')return;
var ICON={"mao": "", "kiem": "", "nhan": "", "daychuyen": ""};
var CF={need:10,lt:1000,rate:.5,useLv:60,maxMake:1,maxLv:10,pierce:.30,dtCd:8000,dtRange:640,
  stat:{1:{a:2,d:2,h:2,m:1000}}};
var SL=[
  {k:'mao',n:'Long Quan Hoàng Kim',t:'Mão',e:'👑',d:'Mão rồng vàng khảm lam ngọc, lông vũ băng.'},
  {k:'kiem',n:'Long Kiếm Hoàng Kim',t:'Kiếm',e:'⚔️',d:'Kiếm đầu rồng vàng, lưỡi băng lam toả sáng.'},
  {k:'nhan',n:'Long Giới Hoàng Kim',t:'Nhẫn',e:'💍',d:'Nhẫn hai rồng vàng ôm viên lam ngọc.'},
  {k:'daychuyen',n:'Long Bội Hoàng Kim',t:'Dây chuyền',e:'📿',d:'Dây chuyền ngọc bội rồng vàng, tua lam.'}];
var GOLD='#f2c14e',busy=false,sel=null,pick=0,lastPE=null,dtCd=0,x3Until=0;
function nf(n){try{return Math.round(n).toLocaleString('vi-VN')}catch(e){return ''+n}}
function ic(k){return 'data:image/webp;base64,'+ICON[k]}
function say(s,c,y){try{DT.push({x:P.x,y:y||180,s:s,c:c||'#ffe9a8',l:110,g:1})}catch(e){}}
function sav(){try{if(typeof sv==='function')sv()}catch(e){}}
function D(i){var p=PS[i==null?cur:i];if(!p)return null;var h=p.hkg;
  if(!h||typeof h!=='object'||!Array.isArray(h.s))h=p.hkg={s:[null,null,null,null]};
  while(h.s.length<4)h.s.push(null);return h}
function statOf(l){return CF.stat[l]||CF.stat[1]}
/* ---------- bộ trang bị: cấp cao nhất mà có ≥k món CÙNG cấp ---------- */
function setLv(k,h){h=h||D();if(!h)return 0;var c={};
  h.s.forEach(function(x){if(x&&x.l>0)c[x.l]=(c[x.l]||0)+1});
  for(var L=CF.maxLv;L>=1;L--)if((c[L]|0)>=k)return L;return 0}
function usable(){try{return (P.lv|0)>=CF.useLv}catch(e){return false}}
function bonus(){
  var o={a:0,d:0,h:0,m:0,l2:0,l3:0,l4:0},h=D();if(!h||!usable())return o;
  h.s.forEach(function(x){if(!x)return;var s=statOf(x.l);o.a+=s.a;o.d+=s.d;o.h+=s.h;o.m+=s.m});
  o.l2=setLv(2,h);o.l3=setLv(3,h);o.l4=setLv(4,h);return o}
var s2=function(L){return L>0?20+5*(L-1):0},s3=function(L){return L>0?1+(L-1):0},dtM=function(L){return 1+.3*(L-1)},dtN=function(L){return Math.min(10,Math.max(1,L))};
/* ---------- chỉ số: nhân % + năng lượng cộng phẳng ---------- */
[['pa','a'],['pd','d'],['ph','h']].forEach(function(z){
  var o=ZC[z[0]];if(typeof o!=='function')return;
  ZC[z[0]]=function(){var r=o.apply(this,arguments);try{var b=bonus()[z[1]];if(b)r*=1+b/100}catch(e){}return r}});
var inMm=0,_pm=ZC.pm;
if(typeof _pm==='function')ZC.pm=function(){
  var r=_pm.apply(this,arguments);if(inMm)return r;
  try{var F=bonus().m;
    if(F>0&&typeof mm==='function'){inMm=1;var m0;try{m0=mm()}finally{inMm=0}if(m0>0)r*=1+F/m0}}catch(e){inMm=0}
  return r};
/* ---------- đòn kỹ năng (SKF=1): bộ 2 món +% · proc ×3 của bộ 3 món ---------- */
var _dm=dm;
dm=function(e,m,sl){
  try{if(SKF){var b=bonus();if(b.l2)m*=1+s2(b.l2)/100;if(b.l3&&fr<x3Until)m*=3}}catch(x){}
  return _dm.call(this,e,m,sl)};
function isClassSkill(n){try{return SK.some(function(k){return k&&k[0]===n})}catch(e){return false}}
function castDT(es,L){
  var n=dtN(L),m=dtM(L),pf=typeof SKF==='number'?SKF:0;
  say('🌍 Địa Tiên','#ffd870',200);
  es.slice(0,n).forEach(function(e){
    try{FX.push({t:'pillar',x:e.x,w:60,c:'#e8b84a',l:34,m:34});
      for(var i=0;i<8;i++)PT.push({x:e.x+(Math.random()-.5)*50,y:50,vx:(Math.random()-.5)*4,vy:Math.random()*3+1,l:30,c:'#d8a640'})}catch(x){}
    var df0=e.df||0;e.df=df0*(1-CF.pierce);SKF=1;
    try{dm(e,m,0)}finally{SKF=pf;e.df=df0}})}
var _tick=ZC.tick;
ZC.tick=function(){
  var r=_tick.apply(this,arguments);
  try{
    if(typeof started==='undefined'||!started||vil||over||!usable())return r;
    var b=bonus();if(!b.l3&&!b.l4)return r;
    var pe=P.pe;
    if(b.l3&&pe&&pe.n&&pe!==lastPE){lastPE=pe;
      if(!isClassSkill(pe.n)&&Math.random()*100<s3(b.l3)){x3Until=fr+(pe.l|0)+150;say('💥 Hoàng Kim ×3','#ffd870',210)}}
    if(b.l4&&Date.now()>=dtCd&&!P.act){
      var es=E.filter(function(e){return e.in<=0&&e.hp>0&&Math.abs(e.x-P.x)<CF.dtRange}).sort(function(a,c){return Math.abs(a.x-P.x)-Math.abs(c.x-P.x)});
      if(es.length){dtCd=Date.now()+CF.dtCd;castDT(es,b.l4)}}
  }catch(e){}
  return r};
/* ---------- giao diện chung ---------- */
var st=document.createElement('style');st.id='hkg-css';
st.textContent='.hkg-bx{max-width:380px!important;max-height:92vh;overflow-y:auto;-webkit-overflow-scrolling:touch}'
+'.hkg-rc{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0}'
+'.hkg-c{border:2px solid #5a4630;border-radius:9px;background:#1a110c;padding:6px;text-align:center;cursor:pointer}'
+'.hkg-c.on{border-color:#ffd870;box-shadow:0 0 8px #f2c14e77}.hkg-c.has{border-color:#6bd08a}'
+'.hkg-c img{width:52px;height:52px;object-fit:contain;display:block;margin:0 auto}.hkg-c b{display:block;font-size:12px;margin-top:2px}.hkg-c em{display:block;font-size:11px;font-style:normal;opacity:.75}'
+'.hkg-box{border:1px solid #5a4630;border-radius:8px;background:#140d0a;padding:8px;margin:6px 0;font-size:12.5px;line-height:1.5}'
+'.hkg-ls{max-height:30vh;overflow-y:auto;border:1px solid #4a3828;border-radius:8px;margin:6px 0}'
+'.hkg-r{display:flex;gap:6px;align-items:center;padding:6px 8px;border-bottom:1px solid #2c1f15;font-size:12px;cursor:pointer}.hkg-r.on{background:#3a2a10}.hkg-r i{font-style:normal;width:18px;text-align:center}.hkg-r span{flex:1;min-width:0}'
+'.hkg-bt{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;margin-top:8px}.hkg-bt button{margin:0!important}.hkg-ok{background:#6a4a14!important;border-color:#ffd870!important}.hkg-ok[disabled]{opacity:.45}'
+'.hkg-on{color:#8ef0a8}.hkg-off{opacity:.6}';
document.head.appendChild(st);
function ov(id){var o=document.getElementById(id);if(o)o.remove();o=document.createElement('div');o.id=id;o.className='tsm-ov';o.style.setProperty('--tc',GOLD);
  o.addEventListener('click',function(e){if(e.target===o)o.remove()});document.body.appendChild(o);return o}
function statTx(l){var s=statOf(l);return '+'+s.a+'% Tấn công · +'+s.d+'% Phòng thủ · +'+s.h+'% Máu · +'+nf(s.m)+' Năng lượng'}
function setHtml(h){
  var a=setLv(2,h),b=setLv(3,h),c=setLv(4,h),sh=function(on,t){return '<div class="'+(on?'hkg-on':'hkg-off')+'">'+(on?'✔ ':'✖ ')+t+'</div>'};
  return '<div class="hkg-box"><b style="color:'+GOLD+'">Bộ Hoàng Kim (món cùng cấp)</b>'
   +sh(a,'2 món: +'+s2(a||1)+'% sát thương kỹ năng (+5% mỗi cấp)')
   +sh(b,'3 món: thần thông có '+s3(b||1)+'% gây ×3 sát thương (+1% mỗi cấp)')
   +sh(c,'4 món: 🌍 Địa Tiên — tự tung mỗi '+(CF.dtCd/1000)+'s: '+Math.round(dtM(c||1)*100)+'% Công lên '+dtN(c||1)+' địch, bỏ qua '+Math.round(CF.pierce*100)+'% giáp (+30% sát thương/cấp, thêm 1 địch/cấp, tối đa 10)')+'</div>'}
function openInfo(i){
  var h=D(),it=h&&h.s[i],sl=SL[i],o=ov('hkg-ov'),lvOk=usable();
  o.innerHTML='<div class="tsm-bx hkg-bx"><h3>👑 '+sl.n+'</h3>'
   +(it?'<div class="hkg-box"><img src="'+ic(sl.k)+'" style="width:64px;height:64px;float:left;margin-right:8px;object-fit:contain"><b>Cấp '+it.l+'/'+CF.maxLv+'</b><br>'+statTx(it.l)+'<br><small style="margin:0">Yêu cầu Lv'+CF.useLv+(lvOk?'':' — <span style="color:#ff8a8a">chưa đủ cấp, chưa có tác dụng</span>')+'</small><div style="clear:both"></div></div><small>'+sl.d+'<br>Nâng cấp lên cấp 2–10: cập nhật sau.</small>'
     :'<small>Ô trống. Chế tạo ở <b>🏯 Làng Tân Thủ 2 → Nhà Chế Tạo Trang Sức Hoàng Kim</b>.<br>Cần '+CF.need+' trang bị Thiên Thần tuỳ ý + '+nf(CF.lt)+'💎 Linh Thạch · thành công '+Math.round(CF.rate*100)+'%.</small>'
       +'<div class="hkg-box"><img src="'+ic(sl.k)+'" style="width:56px;height:56px;float:left;margin-right:8px;object-fit:contain;opacity:.7">Cấp 1: '+statTx(1)+'<div style="clear:both"></div></div>')
   +setHtml(h)
   +'<div class="hkg-bt">'+(it?'':'<button class="tsm-x hkg-ok" onclick="HKG.go()">🏯 Đến Nhà Trang Sức</button>')+'<button class="tsm-x" onclick="document.getElementById(\'hkg-ov\').remove()">Đóng</button></div></div>'}
/* ---------- nhà chế tạo ---------- */
function eligible(){
  var arr=[];try{(BAG||[]).forEach(function(it){if(it&&typeof it==='object'&&it.r===5&&!it.c&&!it.lk&&it.s!==10)arr.push(it)})}catch(e){}
  arr.sort(function(a,b){return (a.a+a.d+a.h)-(b.a+b.d+b.h)});return arr}
function autoPick(){var el=eligible();sel=el.slice(0,CF.need)}
function openCraft(){
  var h=D();if(!h){return}
  if(!sel)sel=[];
  var o=ov('hkg-craft');renderCraft(o)}
function renderCraft(o){
  o=o||document.getElementById('hkg-craft');if(!o)return;
  var h=D(),el=eligible();sel=(sel||[]).filter(function(x){return el.indexOf(x)>=0});
  var made=h.s[pick]?1:0,sl=SL[pick],can=!made&&sel.length===CF.need&&!busy;
  var html='<div class="tsm-bx hkg-bx"><h3>💍 Nhà Chế Tạo Trang Sức Hoàng Kim</h3><small>Chọn món rồi ghép bằng '+CF.need+' trang bị Thiên Thần + '+nf(CF.lt)+'💎. Hiện chỉ chế được cấp 1.</small><div class="hkg-rc">';
  SL.forEach(function(s,i){var it=h.s[i];
    html+='<div class="hkg-c'+(i===pick?' on':'')+(it?' has':'')+'" onclick="HKG.pick('+i+')"><img src="'+ic(s.k)+'"><b>'+s.t+'</b><em>'+(it?'✔ Đã có · Cấp '+it.l:'Chưa chế tạo')+'</em></div>'});
  html+='</div><div class="hkg-box"><b style="color:'+GOLD+'">'+sl.n+'</b><br>Cấp 1: '+statTx(1)+'<br>Yêu cầu dùng: Lv'+CF.useLv+'<br>Chi phí: '+CF.need+' trang bị Thiên Thần tuỳ ý + '+nf(CF.lt)+'💎 Linh Thạch<br>Tỉ lệ thành công: <b>'+Math.round(CF.rate*100)+'%</b> <span style="opacity:.7">(thất bại mất nguyên liệu)</span></div>';
  if(made)html+='<div class="hkg-box hkg-on">✔ Món này đã chế tạo (cấp '+h.s[pick].l+'). Nâng cấp: cập nhật sau.</div>';
  else{
    html+='<div style="display:flex;justify-content:space-between;align-items:center;font-size:12.5px">Trang bị Thiên Thần trong túi: <b>'+el.length+'</b> · Đã chọn <b style="color:'+(sel.length===CF.need?'#8ef0a8':'#ffd870')+'">'+sel.length+'/'+CF.need+'</b></div>';
    html+='<div class="hkg-ls">'+(el.length?el.map(function(it,j){var on=sel.indexOf(it)>=0;
      return '<div class="hkg-r'+(on?' on':'')+'" onclick="HKG.tog('+j+')"><i>'+(on?'☑':'☐')+'</i><span>'+(it.n||'Trang bị')+'</span><small>Lv'+(it.l||'?')+'</small></div>'}).join(''):'<div class="hkg-r" style="cursor:default;opacity:.7">Không có trang bị Thiên Thần nào trong túi.</div>')+'</div>';
    html+='<div class="hkg-bt"><button class="tsm-x" onclick="HKG.auto()">Chọn '+CF.need+' món yếu nhất</button></div>'}
  html+='<div class="hkg-bt"><button class="tsm-x hkg-ok"'+(can?'':' disabled')+' onclick="HKG.make()">🔨 Ghép ('+Math.round(CF.rate*100)+'%)</button><button class="tsm-x" onclick="document.getElementById(\'hkg-craft\').remove()">Đóng</button></div></div>';
  var bx=o.firstElementChild,top=bx?bx.scrollTop:0;o.innerHTML=html;try{o.firstElementChild.scrollTop=top}catch(e){}}
function make(){
  if(busy)return;var h=D();if(!h||h.s[pick])return;
  var el=eligible();sel=(sel||[]).filter(function(x){return el.indexOf(x)>=0});
  if(sel.length!==CF.need){say('Cần chọn đủ '+CF.need+' trang bị Thiên Thần','#ff8a8a',160);return}
  if(!window.LT||!LT.spend||!LT.logged||!LT.logged()){say('☁ Cần đăng nhập tài khoản để dùng Linh Thạch ('+nf(CF.lt)+'💎)','#ff8a8a',160);return}
  if(!confirm('Ghép '+SL[pick].n+'?\nTốn '+CF.need+' trang bị Thiên Thần đã chọn + '+nf(CF.lt)+' Linh Thạch.\nTỉ lệ thành công '+Math.round(CF.rate*100)+'%, thất bại mất nguyên liệu.'))return;
  busy=true;var slot=pick,mats=sel.slice(),idx=mats.map(function(it){return BAG.indexOf(it)});
  if(idx.some(function(i){return i<0})){busy=false;renderCraft();return}
  mats.forEach(function(it){BAG.splice(BAG.indexOf(it),1)});   /* lấy nguyên liệu trước; trừ Linh Thạch lỗi thì trả lại */
  renderCraft();
  LT.spend(CF.lt,'hoangkim'+slot).then(function(res){
    busy=false;
    if(!res||!res.ok){mats.forEach(function(it){BAG.push(it)});
      say(res&&res.err==='poor'?'💎 Không đủ Linh Thạch: cần '+nf(CF.lt)+', có '+nf(res.lt)+'':'Không trừ được Linh Thạch ('+((res&&(res.msg||res.err))||'lỗi')+')','#ff8a8a',160);
      sel=mats;renderCraft();try{ui()}catch(e){}return}
    sel=[];
    if(Math.random()<CF.rate){var hh=D();hh.s[slot]={l:1,t:Date.now()};say('👑 Thành công! '+SL[slot].n+' (Cấp 1)','#ffe27a',240);paint()}
    else say('💥 Thất bại — mất nguyên liệu','#ff8a8a',200);
    sav();try{ui()}catch(e){}renderCraft()
  }).catch(function(){busy=false;mats.forEach(function(it){BAG.push(it)});sel=mats;say('Lỗi mạng khi trừ Linh Thạch','#ff8a8a',140);renderCraft();try{ui()}catch(e){}})}
/* ---------- ô Hoàng Kim ở tab Túi (ui/100) ---------- */
function paint(){
  var h=D();if(!h)return;
  if(window.HK){HK.slots=SL.map(function(s){return{n:s.n,e:s.e}});
    HK.items=h.s.map(function(x,i){return x?{n:SL[i].n,ic:ic(SL[i].k),d:'Cấp '+x.l}:null})}
  var cs=document.querySelectorAll('#bag .hk-row .hk-s');
  for(var i=0;i<cs.length&&i<4;i++){var x=h.s[i];cs[i].className='hk-s '+(x?'on':'em');cs[i].title=SL[i].n;
    var b=cs[i].querySelector('b');if(b)b.innerHTML=x?'<img src="'+ic(SL[i].k)+'">':SL[i].e}}
var _ui=window.ui;
window.ui=function(){var a=_ui.apply(this,arguments);try{paint()}catch(e){}return a};
var sig='';setInterval(function(){if(document.hidden)return;try{var h=D(),s=cur+':'+(h?JSON.stringify(h.s):'');if(s!==sig){sig=s;paint()}}catch(e){}},2000);
/* ---------- gắn vào nhà Trang Sức (world/100) ---------- */
function hook(){try{if(window.TT2&&TT2.houses&&TT2.houses[1]){TT2.houses[1].open=function(){openCraft()};return true}}catch(e){}return false}
if(!hook()){var n=0,iv=setInterval(function(){if(hook()||++n>40)clearInterval(iv)},500)}
window.HKG={cfg:CF,slots:SL,openCraft:openCraft,bonus:bonus,
  pick:function(i){pick=i|0;renderCraft()},
  tog:function(j){var el=eligible(),it=el[j];if(!it)return;var k=sel.indexOf(it);if(k>=0)sel.splice(k,1);else if(sel.length<CF.need)sel.push(it);renderCraft()},
  auto:function(){autoPick();renderCraft()},make:make,
  go:function(){var o=document.getElementById('hkg-ov');if(o)o.remove();if(window.HK&&HK.go)HK.go()},
  give:function(i,l){var h=D();if(h&&SL[i]){h.s[i]={l:l||1,t:Date.now()};sav();paint();try{ui()}catch(e){}}}};
if(window.HK){HK.open=openInfo}
try{paint()}catch(e){}
})();
